class Solution {
    public String abbreviateProduct(int left, int right) {
        java.math.BigInteger product = java.math.BigInteger.ONE;

        for (int i = left; i <= right; i++) {
            product = product.multiply(java.math.BigInteger.valueOf(i));
        }

        String s = product.toString();
        int zeros = 0;
        int end = s.length();

        while (end > 0 && s.charAt(end - 1) == '0') {
            zeros++;
            end--;
        }

        String remaining = s.substring(0, end);

        if (remaining.length() > 10) {
            return remaining.substring(0, 5) + "..." + remaining.substring(remaining.length() - 5) + "e" + zeros;
        }

        return remaining + "e" + zeros;
    }
}
