import java.util.*;

class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> ans = new ArrayList<>();
        String digits = s.substring(1, s.length() - 1);

        for (int i = 1; i < digits.length(); i++) {
            String left = digits.substring(0, i);
            String right = digits.substring(i);

            List<String> leftNums = generate(left);
            List<String> rightNums = generate(right);

            for (String a : leftNums) {
                for (String b : rightNums) {
                    ans.add("(" + a + ", " + b + ")");
                }
            }
        }

        return ans;
    }

    private List<String> generate(String str) {
        List<String> res = new ArrayList<>();
        int n = str.length();

        if (n == 1 || str.charAt(0) != '0') {
            res.add(str);
        }

        for (int i = 1; i < n; i++) {
            String intPart = str.substring(0, i);
            String fracPart = str.substring(i);

            boolean validIntPart = intPart.length() == 1 || intPart.charAt(0) != '0';
            boolean validFracPart = fracPart.charAt(fracPart.length() - 1) != '0';

            if (validIntPart && validFracPart) {
                res.add(intPart + "." + fracPart);
            }
        }

        return res;
    }
}
