class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int roof = m * n;

        int[][] current = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(grid[i], 0, current[i], 0, n);
        }

        for (int[] hit : hits) {
            current[hit[0]][hit[1]] = 0;
        }

        DSU dsu = new DSU(m * n + 1);

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (current[r][c] == 1) {
                    int id = r * n + c;
                    if (r == 0) {
                        dsu.union(id, roof);
                    }
                    if (r > 0 && current[r - 1][c] == 1) {
                        dsu.union(id, (r - 1) * n + c);
                    }
                    if (c > 0 && current[r][c - 1] == 1) {
                        dsu.union(id, r * n + c - 1);
                    }
                }
            }
        }

        int[] result = new int[hits.length];
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int i = hits.length - 1; i >= 0; i--) {
            int r = hits[i][0];
            int c = hits[i][1];

            if (grid[r][c] == 0) {
                result[i] = 0;
                continue;
            }

            int before = dsu.size(roof);

            current[r][c] = 1;
            int id = r * n + c;

            if (r == 0) {
                dsu.union(id, roof);
            }

            for (int[] dir : dirs) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (nr >= 0 && nr < m && nc >= 0 && nc < n && current[nr][nc] == 1) {
                    dsu.union(id, nr * n + nc);
                }
            }

            int after = dsu.size(roof);
            result[i] = Math.max(0, after - before - 1);
        }

        return result;
    }

    static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);

            if (rootA == rootB) {
                return;
            }

            if (size[rootA] < size[rootB]) {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }

            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        int size(int x) {
            return size[find(x)];
        }
    }
}
