    public boolean areOccurrencesEqual(String s) {
        int[] freq = new int[26];

        for (char c : s.toCharArray()) {
            freq[c - 'a']++;
        }

        int target = 0;
        for (int count : freq) {
            if (count > 0) {
                if (target == 0) {
                    target = count;
                } else if (count != target) {
                    return false;
                }
            }
        }

        return true;
    }
