class Solution {
    public int numFactoredBinaryTrees(int[] arr) {
        final long MOD = 1_000_000_007L;

        java.util.Arrays.sort(arr);
        int n = arr.length;

        java.util.HashMap<Integer, Integer> index = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            index.put(arr[i], i);
        }

        long[] dp = new long[n];
        long answer = 0;

        for (int i = 0; i < n; i++) {
            dp[i] = 1;

            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int other = arr[i] / arr[j];
                    Integer k = index.get(other);

                    if (k != null && k < i) {
                        dp[i] = (dp[i] + dp[j] * dp[k]) % MOD;
                    }
                }
            }

            answer = (answer + dp[i]) % MOD;
        }

        return (int) answer;
    }
}
