class Solution {
    public int clumsy(int n) {
        int total = 0;
        int current = n;
        int op = 0;

        for (int x = n - 1; x >= 1; x--) {
            if (op == 0) {
                current *= x;
            } else if (op == 1) {
                current /= x;
            } else if (op == 2) {
                total += current;
                current = x;
            } else {
                total += current;
                current = -x;
            }
            op = (op + 1) % 4;
        }

        return total + current;
    }
}
