class MKAverage {
    private static final int MAX_VAL = 100000;

    private final int m;
    private final int k;
    private final java.util.ArrayDeque<Integer> queue;
    private final Fenwick countTree;
    private final Fenwick sumTree;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        this.queue = new java.util.ArrayDeque<>();
        this.countTree = new Fenwick(MAX_VAL);
        this.sumTree = new Fenwick(MAX_VAL);
    }

    public void addElement(int num) {
        queue.offerLast(num);
        countTree.add(num, 1);
        sumTree.add(num, num);

        if (queue.size() > m) {
            int removed = queue.pollFirst();
            countTree.add(removed, -1);
            sumTree.add(removed, -removed);
        }
    }

    public int calculateMKAverage() {
        if (queue.size() < m) {
            return -1;
        }

        long middleSum = sumFirst(m - k) - sumFirst(k);
        return (int) (middleSum / (m - 2 * k));
    }

    private long sumFirst(int count) {
        int value = countTree.findByOrder(count);
        long countBefore = countTree.query(value - 1);
        long sumBefore = sumTree.query(value - 1);
        return sumBefore + (long) (count - countBefore) * value;
    }

    private static class Fenwick {
        private final int n;
        private final long[] tree;

        Fenwick(int n) {
            this.n = n;
            this.tree = new long[n + 1];
        }

        void add(int index, long delta) {
            while (index <= n) {
                tree[index] += delta;
                index += index & -index;
            }
        }

        long query(int index) {
            long sum = 0;
            while (index > 0) {
                sum += tree[index];
                index -= index & -index;
            }
            return sum;
        }

        int findByOrder(int kth) {
            int index = 0;
            long currentCount = 0;

            for (int bit = Integer.highestOneBit(n); bit != 0; bit >>= 1) {
                int next = index + bit;
                if (next <= n && currentCount + tree[next] < kth) {
                    index = next;
                    currentCount += tree[next];
                }
            }

            return index + 1;
        }
    }
}

