        for (int i = 1; i < n; i++) {
            if (stones[i] - stones[i - 1] > i) {
                return false;
            }
        }

        java.util.Map<Integer, Integer> indexByPosition = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            indexByPosition.put(stones[i], i);
        }

        boolean[][] dp = new boolean[n][n + 1];
        dp[0][0] = true;

        for (int i = 0; i < n; i++) {
            for (int jump = 0; jump <= n; jump++) {
                if (!dp[i][jump]) {
                    continue;
                }

                for (int nextJump = jump - 1; nextJump <= jump + 1; nextJump++) {
                    if (nextJump <= 0 || nextJump > n) {
                        continue;
                    }

                    long nextPositionLong = (long) stones[i] + nextJump;
                    if (nextPositionLong > Integer.MAX_VALUE) {
                        continue;
                    }

                    Integer nextIndex = indexByPosition.get((int) nextPositionLong);
                    if (nextIndex == null) {
                        continue;
                    }

                    if (nextIndex == n - 1) {
                        return true;
                    }

                    dp[nextIndex][nextJump] = true;
                }
            }
        }

        return n == 1;
    }
}
