class Solution {
    private int m;
    private int fullMask;
    private int[][] gcd;
    private int[] memo;

    public int maxScore(int[] nums) {
        m = nums.length;
        fullMask = (1 << m) - 1;
        gcd = new int[m][m];
        memo = new int[1 << m];

        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                gcd[i][j] = gcd(nums[i], nums[j]);
            }
        }

        return dfs(0);
    }

    private int dfs(int mask) {
        if (mask == fullMask) {
            return 0;
        }
        if (memo[mask] != 0) {
            return memo[mask];
        }

        int operation = Integer.bitCount(mask) / 2 + 1;
        int best = 0;

        for (int i = 0; i < m; i++) {
            if ((mask & (1 << i)) != 0) {
                continue;
            }
            for (int j = i + 1; j < m; j++) {
                if ((mask & (1 << j)) != 0) {
                    continue;
                }
                int nextMask = mask | (1 << i) | (1 << j);
                best = Math.max(best, operation * gcd[i][j] + dfs(nextMask));
            }
        }

        memo[mask] = best;
        return best;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }
}
