class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        int n = nums.length;
        int totalSeats = 2 * numSlots;
        int size = 1 << totalSeats;

        int[] dp = new int[size];
        for (int i = 0; i < size; i++) {
            dp[i] = -1;
        }
        dp[0] = 0;

        int answer = 0;

        for (int mask = 0; mask < size; mask++) {
            if (dp[mask] == -1) {
                continue;
            }

            int index = Integer.bitCount(mask);

            if (index == n) {
                answer = Math.max(answer, dp[mask]);
                continue;
            }

            for (int seat = 0; seat < totalSeats; seat++) {
                if ((mask & (1 << seat)) == 0) {
                    int slot = seat / 2 + 1;
                    int nextMask = mask | (1 << seat);
                    int value = dp[mask] + (nums[index] & slot);
                    dp[nextMask] = Math.max(dp[nextMask], value);
                }
            }
        }

        return answer;
    }
}
