class Solution {
    public int maxEqualFreq(int[] nums) {
        int n = nums.length;
        int[] count = new int[100001];
        int[] freqCount = new int[n + 2];

        int maxFreq = 0;
        int answer = 0;

        for (int i = 0; i < n; i++) {
            int num = nums[i];
            int oldFreq = count[num];

            if (oldFreq > 0) {
                freqCount[oldFreq]--;
            }

            int newFreq = oldFreq + 1;
            count[num] = newFreq;
            freqCount[newFreq]++;

            maxFreq = Math.max(maxFreq, newFreq);

            int length = i + 1;

            if (maxFreq == 1
                    || maxFreq * freqCount[maxFreq] + 1 == length
                    || (maxFreq - 1) * (freqCount[maxFreq - 1] + 1) + 1 == length) {
                answer = length;
            }
        }

        return answer;
    }
}
