class Solution {
    public int maxTotalFruits(int[][] fruits, int startPos, int k) {
        int left = 0;
        long sum = 0;
        int ans = 0;

        for (int right = 0; right < fruits.length; right++) {
            sum += fruits[right][1];

            while (left <= right) {
                int lPos = fruits[left][0];
                int rPos = fruits[right][0];
                int steps = (rPos - lPos) + Math.min(Math.abs(startPos - lPos), Math.abs(startPos - rPos));

                if (steps <= k) {
                    break;
                }

                sum -= fruits[left][1];
                left++;
            }

            ans = Math.max(ans, (int) sum);
        }

        return ans;
    }
}
