            while (left <= right) {
                int lPos = fruits[left][0];
                int rPos = fruits[right][0];
                int steps = (rPos - lPos) + Math.min(Math.abs(startPos - lPos), Math.abs(startPos - rPos));

                if (steps <= k) {
                    break;
                }

                sum -= fruits[left][1];
                left++;
            }

            ans = Math.max(ans, (int) sum);
        }

        return ans;
    }
