    public long maxRunTime(int n, int[] batteries) {
        long sum = 0;
        for (int battery : batteries) {
            sum += battery;
        }

        long left = 0;
        long right = sum / n;

        while (left < right) {
            long mid = left + (right - left + 1) / 2;

            long available = 0;
            for (int battery : batteries) {
                available += Math.min((long) battery, mid);
            }

            if (available >= mid * n) {
                left = mid;
            } else {
                right = mid - 1;
            }
        }

        return left;
    }
