class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length;
        int n = seats[0].length;
        int totalMasks = 1 << n;

        int[] available = new int[m];
        for (int i = 0; i < m; i++) {
            int mask = 0;
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') {
                    mask |= 1 << j;
                }
            }
            available[i] = mask;
        }

        int[] count = new int[totalMasks];
        for (int mask = 0; mask < totalMasks; mask++) {
            count[mask] = Integer.bitCount(mask);
        }

        int[] prev = new int[totalMasks];
        int[] curr = new int[totalMasks];
        java.util.Arrays.fill(prev, -1);
        prev[0] = 0;

        for (int row = 0; row < m; row++) {
            java.util.Arrays.fill(curr, -1);

            for (int mask = 0; mask < totalMasks; mask++) {
                if ((mask & ~available[row]) != 0) {
                    continue;
                }
                if ((mask & (mask << 1)) != 0) {
                    continue;
                }

                for (int prevMask = 0; prevMask < totalMasks; prevMask++) {
                    if (prev[prevMask] == -1) {
                        continue;
                    }
                    if ((mask & (prevMask << 1)) != 0) {
                        continue;
                    }
                    if ((mask & (prevMask >> 1)) != 0) {
                        continue;
                    }

                    curr[mask] = Math.max(curr[mask], prev[prevMask] + count[mask]);
                }
            }

            int[] temp = prev;
            prev = curr;
            curr = temp;
        }

        int answer = 0;
        for (int value : prev) {
            answer = Math.max(answer, value);
        }

        return answer;
    }
}
