class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        java.util.Arrays.sort(flowers);

        int n = flowers.length;
        int m = 0;
        while (m < n && flowers[m] < target) {
            m++;
        }

        int alreadyFull = n - m;

        long[] prefix = new long[m + 1];
        for (int i = 0; i < m; i++) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }

        long ans = 0;
        long completeCost = 0;

        for (int t = 0; t <= m; t++) {
            if (t > 0) {
                completeCost += (long) target - flowers[m - t];
            }

            if (completeCost > newFlowers) {
                break;
            }

            int remaining = m - t;
            long beauty = (long) (alreadyFull + t) * full;

            if (remaining > 0) {
                int minIncomplete = maxPartial(flowers, prefix, remaining, newFlowers - completeCost, target);
                beauty += (long) minIncomplete * partial;
            }

            ans = Math.max(ans, beauty);
        }

        return ans;
    }

    private int maxPartial(int[] flowers, long[] prefix, int len, long budget, int target) {
        int lo = 0;
        int hi = target - 1;

        while (lo < hi) {
            int mid = (lo + hi + 1) >>> 1;
            if (canRaise(flowers, prefix, len, budget, mid)) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }

        return lo;
    }

    private boolean canRaise(int[] flowers, long[] prefix, int len, long budget, int value) {
        int count = lowerBound(flowers, len, value);
        long cost = (long) value * count - prefix[count];
        return cost <= budget;
    }

    private int lowerBound(int[] flowers, int len, int value) {
        int left = 0;
        int right = len;

        while (left < right) {
            int mid = (left + right) >>> 1;
            if (flowers[mid] < value) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return left;
    }
}
