class Solution {
    public int minAreaRect(int[][] points) {
        int n = points.length;
        HashSet<Integer> set = new HashSet<>();
        int base = 40001;

        for (int[] p : points) {
            set.add(p[0] * base + p[1]);
        }

        int minArea = Integer.MAX_VALUE;

        for (int i = 0; i < n; i++) {
            int x1 = points[i][0];
            int y1 = points[i][1];

            for (int j = i + 1; j < n; j++) {
                int x2 = points[j][0];
                int y2 = points[j][1];

                if (x1 != x2 && y1 != y2) {
                    if (set.contains(x1 * base + y2) && set.contains(x2 * base + y1)) {
                        int area = Math.abs(x1 - x2) * Math.abs(y1 - y2);
                        minArea = Math.min(minArea, area);
                    }
                }
            }
        }

        return minArea == Integer.MAX_VALUE ? 0 : minArea;
    }
