class Solution {
    private static final long MOD = 1_000_000_007L;
    private long[][] comb;

    public int numOfWays(int[] nums) {
        int n = nums.length;
        comb = new long[n + 1][n + 1];

        for (int i = 0; i <= n; i++) {
            comb[i][0] = 1;
            comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
            }
        }

        java.util.List<Integer> list = new java.util.ArrayList<>();
        for (int num : nums) {
            list.add(num);
        }

        return (int) ((countWays(list) - 1 + MOD) % MOD);
    }

    private long countWays(java.util.List<Integer> nums) {
        int size = nums.size();
        if (size <= 2) {
            return 1;
        }

        int root = nums.get(0);
        java.util.List<Integer> left = new java.util.ArrayList<>();
        java.util.List<Integer> right = new java.util.ArrayList<>();

        for (int i = 1; i < size; i++) {
            int num = nums.get(i);
            if (num < root) {
                left.add(num);
            } else {
                right.add(num);
            }
        }

        long leftWays = countWays(left);
        long rightWays = countWays(right);

        return (((comb[size - 1][left.size()] * leftWays) % MOD) * rightWays) % MOD;
    }
}
