class Solution {
    public int maxSizeSlices(int[] slices) {
        int n = slices.length;
        int pick = n / 3;
        return Math.max(maxLinear(slices, 0, n - 2, pick), maxLinear(slices, 1, n - 1, pick));
    }

    private int maxLinear(int[] slices, int start, int end, int pick) {
        int m = end - start + 1;
        int[][] dp = new int[m + 1][pick + 1];

        for (int i = 1; i <= m; i++) {
            int value = slices[start + i - 1];
            for (int j = 1; j <= pick; j++) {
                dp[i][j] = dp[i - 1][j];
                int take = value;
                if (i >= 2) {
                    take += dp[i - 2][j - 1];
                }
                dp[i][j] = Math.max(dp[i][j], take);
            }
        }

        return dp[m][pick];
    }
}
