class Solution {
    private int[] parent;
    private int[] size;

    public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
        parent = new int[n];
        size = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        boolean[] result = new boolean[requests.length];

        for (int i = 0; i < requests.length; i++) {
            int u = requests[i][0];
            int v = requests[i][1];

            int rootU = find(u);
            int rootV = find(v);

            boolean canBeFriends = true;

            if (rootU != rootV) {
                for (int[] restriction : restrictions) {
                    int rootA = find(restriction[0]);
                    int rootB = find(restriction[1]);

                    if ((rootA == rootU && rootB == rootV) || (rootA == rootV && rootB == rootU)) {
                        canBeFriends = false;
                        break;
                    }
                }
            }

            if (canBeFriends) {
                union(rootU, rootV);
                result[i] = true;
            } else {
                result[i] = false;
            }
        }

        return result;
    }

    private int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    private void union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);

        if (rootA == rootB) {
            return;
        }

        if (size[rootA] < size[rootB]) {
            parent[rootA] = rootB;
            size[rootB] += size[rootA];
        } else {
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }
    }
}
