class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int totalMasks = 1 << n;

        int[] sum = new int[totalMasks];
        for (int mask = 1; mask < totalMasks; mask++) {
            int lsb = mask & -mask;
            int idx = Integer.numberOfTrailingZeros(lsb);
            sum[mask] = sum[mask ^ lsb] + tasks[idx];
        }

        int[] dp = new int[totalMasks];
        for (int i = 1; i < totalMasks; i++) {
            dp[i] = n;
        }

        for (int mask = 1; mask < totalMasks; mask++) {
            if (sum[mask] <= sessionTime) {
                dp[mask] = 1;
                continue;
            }

            for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
                if (sum[sub] <= sessionTime) {
                    dp[mask] = Math.min(dp[mask], dp[mask ^ sub] + 1);
                }
            }
        }

        return dp[totalMasks - 1];
    }
