class Solution {
    public int numTriplets(int[] nums1, int[] nums2) {
        long ans = 0;

        Map<Long, Integer> products2 = countPairProducts(nums2);
        for (int num : nums1) {
            long square = (long) num * num;
            ans += products2.getOrDefault(square, 0);
        }

        Map<Long, Integer> products1 = countPairProducts(nums1);
        for (int num : nums2) {
            long square = (long) num * num;
            ans += products1.getOrDefault(square, 0);
        }

        return (int) ans;
    }

    private Map<Long, Integer> countPairProducts(int[] nums) {
        Map<Long, Integer> map = new HashMap<>();

        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                long product = (long) nums[i] * nums[j];
                map.put(product, map.getOrDefault(product, 0) + 1);
            }
        }

        return map;
    }
