import java.util.*;

class Solution {
    private int[][] stickerCounts;
    private Map<String, Integer> memo;

    public int minStickers(String[] stickers, String target) {
        int n = stickers.length;
        stickerCounts = new int[n][26];
        boolean[] available = new boolean[26];

        for (int i = 0; i < n; i++) {
            for (char c : stickers[i].toCharArray()) {
                stickerCounts[i][c - 'a']++;
                available[c - 'a'] = true;
            }
        }

        for (char c : target.toCharArray()) {
            if (!available[c - 'a']) {
                return -1;
            }
        }

        char[] chars = target.toCharArray();
        Arrays.sort(chars);
        target = new String(chars);

        memo = new HashMap<>();
        memo.put("", 0);

        return dfs(target);
    }

    private int dfs(String target) {
        if (memo.containsKey(target)) {
            return memo.get(target);
        }

        int[] need = new int[26];
        for (char c : target.toCharArray()) {
            need[c - 'a']++;
        }

        int firstChar = target.charAt(0) - 'a';
        int result = Integer.MAX_VALUE;

        for (int[] sticker : stickerCounts) {
            if (sticker[firstChar] == 0) {
                continue;
            }

            StringBuilder nextTarget = new StringBuilder();

            for (int i = 0; i < 26; i++) {
                int remaining = need[i] - sticker[i];
                for (int j = 0; j < remaining; j++) {
                    nextTarget.append((char) ('a' + i));
                }
            }

            int subResult = dfs(nextTarget.toString());

            if (subResult != -1) {
                result = Math.min(result, 1 + subResult);
            }
        }

        int answer = result == Integer.MAX_VALUE ? -1 : result;
        memo.put(target, answer);
        return answer;
    }
}
