import java.util.*;

class Solution {
    private Map<Integer, int[]> memo;

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memo = new HashMap<>();
        return solve(n, firstPlayer, secondPlayer);
    }

    private int[] solve(int n, int first, int second) {
        if (first + second == n + 1) {
            return new int[]{1, 1};
        }

        int key = (n << 10) | (first << 5) | second;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        Set<Integer> nextStates = new HashSet<>();
        generateNextStates(1, n, first, second, 0, 0, nextStates);

        int nextN = (n + 1) / 2;
        int earliest = Integer.MAX_VALUE;
        int latest = Integer.MIN_VALUE;

        for (int state : nextStates) {
            int nextFirst = state >> 5;
            int nextSecond = state & 31;

            int[] result = solve(nextN, nextFirst, nextSecond);
            earliest = Math.min(earliest, result[0] + 1);
            latest = Math.max(latest, result[1] + 1);
        }

        int[] answer = new int[]{earliest, latest};
        memo.put(key, answer);
        return answer;
    }

    private void generateNextStates(
            int pairIndex,
            int n,
            int first,
            int second,
            int beforeFirst,
            int beforeSecond,
            Set<Integer> nextStates
    ) {
        int half = n / 2;

        if (pairIndex > half) {
            if (n % 2 == 1) {
                int middle = half + 1;
                if (middle < first) beforeFirst++;
                if (middle < second) beforeSecond++;
            }

            int nextFirst = beforeFirst + 1;
            int nextSecond = beforeSecond + 1;
            nextStates.add((nextFirst << 5) | nextSecond);
            return;
        }

        int left = pairIndex;
        int right = n + 1 - pairIndex;

        if (left == first || right == first) {
            addWinner(pairIndex, n, first, second, beforeFirst, beforeSecond, nextStates, first);
        } else if (left == second || right == second) {
            addWinner(pairIndex, n, first, second, beforeFirst, beforeSecond, nextStates, second);
        } else {
            addWinner(pairIndex, n, first, second, beforeFirst, beforeSecond, nextStates, left);
            addWinner(pairIndex, n, first, second, beforeFirst, beforeSecond, nextStates, right);
        }
    }

    private void addWinner(
            int pairIndex,
            int n,
            int first,
            int second,
            int beforeFirst,
            int beforeSecond,
            Set<Integer> nextStates,
            int winner
    ) {
        if (winner < first) beforeFirst++;
        if (winner < second) beforeSecond++;

        generateNextStates(
                pairIndex + 1,
                n,
                first,
                second,
                beforeFirst,
                beforeSecond,
                nextStates
        );
    }
}
