class Solution {
    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;

        int[] head = new int[n];
        for (int i = 0; i < n; i++) head[i] = -1;

        int[] to = new int[2 * edges.length];
        int[] next = new int[2 * edges.length];
        int idx = 0;

        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];

            to[idx] = v;
            next[idx] = head[u];
            head[u] = idx++;

            to[idx] = u;
            next[idx] = head[v];
            head[v] = idx++;
        }

        boolean[][] coprime = new boolean[51][51];
        for (int i = 1; i <= 50; i++) {
            for (int j = 1; j <= 50; j++) {
                coprime[i][j] = gcd(i, j) == 1;
            }
        }

        int[] ans = new int[n];
        for (int i = 0; i < n; i++) ans[i] = -1;

        int[] depth = new int[n];
        int[][] valueStacks = new int[51][n];
        int[] top = new int[51];

        int maxStackSize = 2 * n + 5;
        int[] stackNode = new int[maxStackSize];
        int[] stackParent = new int[maxStackSize];
        int[] stackDepth = new int[maxStackSize];
        int[] stackState = new int[maxStackSize];
        int sp = 0;

        stackNode[sp] = 0;
        stackParent[sp] = -1;
        stackDepth[sp] = 0;
        stackState[sp] = 0;
        sp++;

        while (sp > 0) {
            sp--;
            int node = stackNode[sp];
            int parent = stackParent[sp];
            int d = stackDepth[sp];
            int state = stackState[sp];

            int val = nums[node];

            if (state == 1) {
                top[val]--;
                continue;
            }

            depth[node] = d;

            int bestNode = -1;
            int bestDepth = -1;

            for (int ancestorVal = 1; ancestorVal <= 50; ancestorVal++) {
                if (coprime[val][ancestorVal] && top[ancestorVal] > 0) {
                    int ancestor = valueStacks[ancestorVal][top[ancestorVal] - 1];
                    if (depth[ancestor] > bestDepth) {
                        bestDepth = depth[ancestor];
                        bestNode = ancestor;
                    }
                }
            }

            ans[node] = bestNode;

            valueStacks[val][top[val]++] = node;

            stackNode[sp] = node;
            stackParent[sp] = parent;
            stackDepth[sp] = d;
            stackState[sp] = 1;
            sp++;

            for (int e = head[node]; e != -1; e = next[e]) {
                int child = to[e];
                if (child == parent) continue;

                stackNode[sp] = child;
                stackParent[sp] = node;
                stackDepth[sp] = d + 1;
                stackState[sp] = 0;
                sp++;
            }
        }

        return ans;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}
