class Solution {
    private String[] words;
    private String result;
    private int[] map;
    private boolean[] used;
    private boolean[] nonZero;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        this.map = new int[26];
        this.used = new boolean[10];
        this.nonZero = new boolean[26];

        for (int i = 0; i < 26; i++) {
            map[i] = -1;
        }

        boolean[] seen = new boolean[26];
        int unique = 0;
        int maxWordLen = 0;

        for (String word : words) {
            maxWordLen = Math.max(maxWordLen, word.length());

            if (word.length() > 1) {
                nonZero[word.charAt(0) - 'A'] = true;
            }

            for (char c : word.toCharArray()) {
                int idx = c - 'A';
                if (!seen[idx]) {
                    seen[idx] = true;
                    unique++;
                }
            }
        }

        if (result.length() > 1) {
            nonZero[result.charAt(0) - 'A'] = true;
        }

        for (char c : result.toCharArray()) {
            int idx = c - 'A';
            if (!seen[idx]) {
                seen[idx] = true;
                unique++;
            }
        }

        if (unique > 10) {
            return false;
        }

        if (maxWordLen > result.length()) {
            return false;
        }

        if (result.length() > maxWordLen + 1) {
            return false;
        }

        return dfs(0, 0, 0);
    }

    private boolean dfs(int col, int row, int sum) {
        if (col == result.length()) {
            return sum == 0;
        }

        if (row < words.length) {
            String word = words[row];

            if (col >= word.length()) {
                return dfs(col, row + 1, sum);
            }

            char c = word.charAt(word.length() - 1 - col);
            int idx = c - 'A';

            if (map[idx] != -1) {
                return dfs(col, row + 1, sum + map[idx]);
            }

            for (int digit = 0; digit <= 9; digit++) {
                if (used[digit]) {
                    continue;
                }

                if (digit == 0 && nonZero[idx]) {
                    continue;
                }

                map[idx] = digit;
                used[digit] = true;

                if (dfs(col, row + 1, sum + digit)) {
                    return true;
                }

                used[digit] = false;
                map[idx] = -1;
            }

            return false;
        }

        char c = result.charAt(result.length() - 1 - col);
        int idx = c - 'A';
        int digit = sum % 10;
        int carry = sum / 10;

        if (map[idx] != -1) {
            if (map[idx] != digit) {
                return false;
            }
            return dfs(col + 1, 0, carry);
        }

        if (used[digit]) {
            return false;
        }

        if (digit == 0 && nonZero[idx]) {
            return false;
        }

        map[idx] = digit;
        used[digit] = true;

        if (dfs(col + 1, 0, carry)) {
            return true;
        }

        used[digit] = false;
        map[idx] = -1;

        return false;
    }
}
