class Solution {
    public boolean validateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] indegree = new int[n];

        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1) {
                indegree[leftChild[i]]++;
                if (indegree[leftChild[i]] > 1) {
                    return false;
                }
            }

            if (rightChild[i] != -1) {
                indegree[rightChild[i]]++;
                if (indegree[rightChild[i]] > 1) {
                    return false;
                }
            }
        }

        int root = -1;
        int rootCount = 0;

        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                root = i;
                rootCount++;
            }
        }

        if (rootCount != 1) {
            return false;
        }

        boolean[] visited = new boolean[n];
        int[] queue = new int[n];
        int front = 0;
        int back = 0;
        int visitedCount = 0;

        queue[back++] = root;
        visited[root] = true;

        while (front < back) {
            int node = queue[front++];
            visitedCount++;

            int left = leftChild[node];
            if (left != -1) {
                if (visited[left]) {
                    return false;
                }
                visited[left] = true;
                queue[back++] = left;
            }

            int right = rightChild[node];
            if (right != -1) {
                if (visited[right]) {
                    return false;
                }
                visited[right] = true;
                queue[back++] = right;
            }
        }

        return visitedCount == n;
    }
}
